   543  pdf_obj *
   544  pdf_parse_array(fz_context *ctx, pdf_document *doc, fz_stream *file, pdf_lexbuf *buf)
   545  {
   546          pdf_obj *ary = NULL;
   547          pdf_obj *obj = NULL;
   548          int64_t a = 0, b = 0, n = 0;
   549          pdf_token tok;
   550          pdf_obj *op = NULL;
   551
   552          fz_var(obj);
   553
   554          ary = pdf_new_array(ctx, doc, 4);
   555
   556          fz_try(ctx)
   557          {
   558                  while (1)
   559                  {
   560                          tok = pdf_lex(ctx, file, buf);
   561
   562                          if (tok != PDF_TOK_INT && tok != PDF_TOK_R)
   563                          {
   564                                  if (n > 0)
   565                                          pdf_array_push_int(ctx, ary, a);
   566                                  if (n > 1)
   567                                          pdf_array_push_int(ctx, ary, b);
   568                                  n = 0;
   569                          }
   570
   571                          if (tok == PDF_TOK_INT && n == 2)
   572                          {
   573                                  pdf_array_push_int(ctx, ary, a);
   574                                  a = b;
   575                                  n --;
   576                          }
   577
   578                          switch (tok)
   579                          {
   580                          case PDF_TOK_EOF:
   581                                  fz_throw(ctx, FZ_ERROR_SYNTAX, "array not closed before end of file");
   582
   583                          case PDF_TOK_CLOSE_ARRAY:
   584                                  op = ary;
   585                                  goto end;
   586
   587                          case PDF_TOK_INT:
   588                                  if (n == 0)
   589                                          a = buf->i;
   590                                  if (n == 1)
   591                                          b = buf->i;
   592                                  n ++;
   593                                  break;
   594
   595                          case PDF_TOK_R:
   596                                  if (n != 2)
   597                                          fz_throw(ctx, FZ_ERROR_SYNTAX, "cannot parse indirect reference in array");
   598                                  pdf_array_push_drop(ctx, ary, pdf_new_indirect(ctx, doc, a, b));
   599                                  n = 0;
   600                                  break;
   601
   602                          case PDF_TOK_OPEN_ARRAY:
   603                                  obj = pdf_parse_array(ctx, doc, file, buf);
   604                                  pdf_array_push_drop(ctx, ary, obj);
   605                                  break;
   606
   607                          case PDF_TOK_OPEN_DICT:
   608                                  obj = pdf_parse_dict(ctx, doc, file, buf);
   609                                  pdf_array_push_drop(ctx, ary, obj);
   610                                  break;
   611
   612                          case PDF_TOK_NAME:
   613                                  pdf_array_push_name(ctx, ary, buf->scratch);
   614                                  break;
   615                          case PDF_TOK_REAL:
   616                                  pdf_array_push_real(ctx, ary, buf->f);
   617                                  break;
   618                          case PDF_TOK_STRING:
   619                                  pdf_array_push_string(ctx, ary, buf->scratch, buf->len);
   620                                  break;
   621                          case PDF_TOK_TRUE:
   622                                  pdf_array_push_bool(ctx, ary, 1);
   623                                  break;
   624                          case PDF_TOK_FALSE:
   625                                  pdf_array_push_bool(ctx, ary, 0);
   626                                  break;
   627                          case PDF_TOK_NULL:
   628                                  pdf_array_push(ctx, ary, PDF_NULL);
   629                                  break;
   630
   631                          default:
   632                                  pdf_array_push(ctx, ary, PDF_NULL);
   633                                  break;
   634                          }
   635                  }
   636  end:
   637                  {}
   638          }
   639          fz_catch(ctx)
   640          {
   641                  pdf_drop_obj(ctx, ary);
   642                  fz_rethrow(ctx);
   643          }
   644          return op;
   645  }
