    57   * Scan stream dictionary for an explicit /Crypt filter
    58   */
    59  static int
    60  pdf_stream_has_crypt(fz_context *ctx, pdf_obj *stm)
    61  {
    62          pdf_obj *filters;
    63          pdf_obj *obj;
    64          int i;
    65
    66          filters = pdf_dict_geta(ctx, stm, PDF_NAME(Filter), PDF_NAME(F));
    67          if (filters)
    68          {
    69                  if (pdf_name_eq(ctx, filters, PDF_NAME(Crypt)))
    70                          return 1;
    71                  if (pdf_is_array(ctx, filters))
    72                  {
    73                          int n = pdf_array_len(ctx, filters);
    74                          for (i = 0; i < n; i++)
    75                          {
    76                                  obj = pdf_array_get(ctx, filters, i);
    77                                  if (pdf_name_eq(ctx, obj, PDF_NAME(Crypt)))
    78                                          return 1;
    79                          }
    80                  }
    81          }
    82          return 0;
    83  }
